    )
    .handle(
      "skill.remove",
      Effect.fn(function* (ctx) {
        const skill = yield* SkillV2.Service
        const location = yield* Location.Service
        return yield* response(skill.remove(location.directory, ctx.query.path).pipe(Effect.as(true))).pipe(
